            }
        });
    }

    @RolesAllowed(UserRole.USER)
    public void deleteAvatar(UUID id) {

        Path avatarPath = Paths.get(avatarStore, id + ".png");

        try {
            if (Files.deleteIfExists(avatarPath)) {
                System.out.println("Deleted avatar for user: " + id);
            } else {
